/**
 * @example
 * import { createServer } from 'node:http';
 * const res = await fetch('https://example.invalid/');
 */
// fetch() leaves them alone, and so does this interceptor.
// It uses "eval()" calls to create a separate source file in devtools.
const templates = [
  'var bytes = await res.arrayBuffer();',
  "WebAssembly.compile(bytes)",
];
const bailout = "eval()";
class Value {
  eval(context) { return this; }
}
const dynamicImport = new Function('specifier', 'return import(specifier)');
const loadVite = new Function('return import("vite")');
const PromiseImpl = new Function('return this;')().Promise;
module.exports = { templates, bailout, Value, dynamicImport, loadVite, PromiseImpl };
